using System;using System.IO;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad] public static class PolishReproductionV06 {
  const string Active="ZTM_POLISH_REPRO_V06";static GameView view;static RenderTexture target;static int phase,warm;static double started;static bool expectFixed;static StringBuilder report=new StringBuilder();
  static string Root=>Directory.GetParent(Application.dataPath).FullName;
  static PolishReproductionV06(){EditorApplication.update+=Tick;}
  public static string Start(bool fixedVersion){if(EditorApplication.isPlaying)throw new Exception("Own Editor already playing");SessionState.SetBool("ZTM_POLISH_REPRO_FIXED",fixedVersion);expectFixed=fixedVersion;view=null;phase=warm=0;report=new StringBuilder();started=EditorApplication.timeSinceStartup;Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","polish-v06-reproduction-save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Active,true);EditorApplication.EnterPlaymode();return "queued";}
  static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
  static void Capture(string name){var old=RenderTexture.active;RenderTexture.active=target;var t=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,target.width,target.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","polish-v06-"+(expectFixed?"fixed-":"before-")+name+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);RenderTexture.active=old;}
  static void Tick(){if(!SessionState.GetBool(Active,false)||!EditorApplication.isPlaying)return;try{
   if(started==0){started=EditorApplication.timeSinceStartup;expectFixed=SessionState.GetBool("ZTM_POLISH_REPRO_FIXED",false);}
   if(EditorApplication.timeSinceStartup-started>90)throw new Exception("Timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;target=new RenderTexture(480,960,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;var s=new PlayerState{cash=20,spins=1};s.fragments[0]=2;view.SetQaState(s,0);phase=1;warm=0;}
   if(++warm<30)return;
   if(phase==1){var ring=UI.Q<VisualElement>("tutorial-highlight");report.AppendLine("initialRing="+(ring!=null)+" initialStep="+TutorialPolicy.Step(view.Model.Snapshot));Capture("context-before-spin");view.QaClick("spin");phase=2;warm=0;}
   else if(phase==2){if(view.QaSpinning||UI.Q<VisualElement>("reward-to-task").resolvedStyle.display==DisplayStyle.Flex){warm=0;return;}if(warm<20)return;var card=UI.Q<VisualElement>("active-quest");var ring=UI.Q<VisualElement>("tutorial-highlight");bool attached=ring!=null&&ring.parent==card&&ring.panel==UI.panel;report.AppendLine("afterActualSpin step="+TutorialPolicy.Step(view.Model.Snapshot)+" spins="+view.Model.Snapshot.spins+" ringAttachedToCurrentCard="+attached);Capture("context-after-spin");if(expectFixed&&!attached)throw new Exception("highlight lost after collection redraw");var s=new PlayerState{cash=60,spins=4};s.fragments[0]=20;view.SetQaState(s,0);phase=3;warm=0;}
   else if(phase==3){var label=UI.Q<Label>("fragment-count-0");var natural=label.MeasureTextSize(label.text,0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);var wrapped=label.MeasureTextSize(label.text,label.contentRect.width,VisualElement.MeasureMode.Exactly,0,VisualElement.MeasureMode.Undefined);bool fits=natural.x<=label.contentRect.width+1&&wrapped.y<=label.contentRect.height+1;report.AppendLine("fullCount="+label.text+" natural="+natural+" wrapped="+wrapped+" rect="+label.contentRect+" fits="+fits);Capture("full-counter");if(expectFixed&&!fits)throw new Exception("full counter clipped or wrapped");Finish();}
  }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish();}}
  static void Finish(){SessionState.SetBool(Active,false);report.AppendLine("coverage=Editor UI callbacks and actual rendered target; no OS/human input");File.WriteAllText(Path.Combine(Root,"Evidence","polish-v06-"+(expectFixed?"fixed":"before")+"-reproduction.txt"),report.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();Debug.Log(report.ToString());}
 }
}
